<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\ContactMessage;use App\Models\ContactPage;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class ContactPageController extends Controller {public function edit():View{return view('admin.contact.edit',['settings'=>ContactPage::firstOrCreate([])]);}public function update(Request $r):RedirectResponse{$data=$r->validate(['page_title'=>['required','string','max:255'],'office_title'=>['required','string','max:255'],'office_description'=>['nullable','string','max:2000'],'branches_title'=>['required','string','max:255'],'branches_description'=>['nullable','string','max:2000'],'form_title'=>['required','string','max:255'],'form_description'=>['nullable','string','max:2000'],'call_button_text'=>['required','string','max:100'],'call_number'=>['nullable','string','max:50'],'submit_button_text'=>['required','string','max:100'],'agreement_text'=>['nullable','string','max:1000'],'terms_url'=>['nullable','string','max:1000'],'privacy_url'=>['nullable','string','max:1000'],'map_title'=>['required','string','max:255'],'map_embed_url'=>['nullable','url','max:3000']]);ContactPage::firstOrCreate([])->update($data);return back()->with('status','Contact page updated successfully.');}public function messages():View{return view('admin.contact.messages',['messages'=>ContactMessage::latest()->paginate(25)]);}public function show(ContactMessage $message):View{$message->update(['is_read'=>true]);return view('admin.contact.show',compact('message'));}public function destroy(ContactMessage $message):RedirectResponse{$message->delete();return redirect()->route('admin.contact.messages')->with('status','Message deleted successfully.');}}
